// Liefert Status-Events einer Session (Polling-Endpoint fuer Web-Clients)
const q = $('Status Webhook').first().json.query || {};
const sid = q.session_id || '';
const after = parseInt(q.after || '0', 10) || 0;
if (!sid) return [{ json: { events: [] } }];
const rows = await helpers.httpRequest({
  method: 'GET',
  url: '{{SUPABASE_URL}}/rest/v1/agent_status?session_id=eq.' + encodeURIComponent(sid) + '&id=gt.' + after + '&select=id,message,created_at&order=id.asc&limit=50',
  headers: { 'apikey': '{{SUPABASE_SERVICE_KEY}}' }
});
// Selbstreinigung: Events aelter als 1 Stunde entsorgen (best effort)
try {
  await helpers.httpRequest({
    method: 'DELETE',
    url: '{{SUPABASE_URL}}/rest/v1/agent_status?created_at=lt.' + encodeURIComponent(new Date(Date.now() - 3600000).toISOString()),
    headers: { 'apikey': '{{SUPABASE_SERVICE_KEY}}' }
  });
} catch (_e) {}
return [{ json: { events: Array.isArray(rows) ? rows : [] } }];
